import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import postgres from "postgres";

const MIGRATIONS_DIR = path.join(import.meta.dirname, "migrations");
const HARDENING_DIR = path.join(MIGRATIONS_DIR, "hardening");

/** Runtime DB role the app connects as (see ADR 0008 — must NOT be a superuser). */
const APP_ROLE = "quodera_app";

/**
 * Apply every pending .sql migration, in order:
 *
 *   0. bootstrap the non-superuser runtime role (quodera_app)
 *   1. migrations/*.sql          — generated by `pnpm db:generate` (drizzle-kit)
 *   2. migrations/hardening/*.sql — hand-written RLS / policy / grant SQL that
 *      drizzle's schema language cannot express
 *
 * MUST run over an admin connection (DATABASE_ADMIN_URL — superuser or table
 * owner). Applied files are recorded in `_quodera_migrations`, so this is
 * idempotent and works identically against local Docker, the CI service
 * container, and Neon. Migrations are forward-only — never edit an applied
 * file (GUARDRAILS #7); write a new one instead.
 */
export async function applyMigrations(databaseUrl: string): Promise<string[]> {
  const sql = postgres(databaseUrl, { prepare: false, max: 1 });
  const applied: string[] = [];

  try {
    // pgvector must be active before the first migration (it declares a
    // vector(8) column). The Docker/CI image ships the extension unactivated;
    // Neon needs it once per project.
    await sql`create extension if not exists vector`;

    await sql`create table if not exists _quodera_migrations (
      name text primary key,
      applied_at timestamptz not null default now()
    )`;

    await bootstrapAppRole(sql);

    const files: Array<{ name: string; abs: string }> = [];
    for (const dir of [MIGRATIONS_DIR, HARDENING_DIR]) {
      let entries: string[];
      try {
        entries = readdirSync(dir);
      } catch {
        continue; // directory does not exist yet — nothing to apply from it
      }
      for (const entry of entries.filter((f) => f.endsWith(".sql")).sort()) {
        // stable tracking name relative to migrations/, e.g. "0000_x.sql" or
        // "hardening/0001_y.sql"
        files.push({
          name: path.relative(MIGRATIONS_DIR, path.join(dir, entry)),
          abs: path.join(dir, entry),
        });
      }
    }

    for (const file of files) {
      const already = await sql`select name from _quodera_migrations where name = ${file.name}`;
      if (already.length > 0) continue;

      // postgres.js runs paramless unsafe() as a simple query, so one file may
      // contain multiple statements (including drizzle's breakpoint comments).
      await sql.unsafe(readFileSync(file.abs, "utf8"));
      await sql`insert into _quodera_migrations (name) values (${file.name})`;
      applied.push(file.name);
    }
  } finally {
    await sql.end({ timeout: 5 });
  }

  return applied;
}

/**
 * Ensure the runtime role exists. RLS only ever binds non-superuser roles —
 * connecting as the container's `postgres` (or any superuser) silently bypasses
 * every policy, which is precisely what rls.test.ts exists to prevent.
 *
 * The role's password comes from APP_DB_PASSWORD; the committed default is a
 * throwaway for local Docker. In production the value is set only in the
 * migration environment (never committed) — see docs/ops/PROVISIONING.md §5.
 */
async function bootstrapAppRole(sql: postgres.Sql): Promise<void> {
  const password = (process.env.APP_DB_PASSWORD ?? "quodera_app_dev").replace(/'/g, "''");
  if (!/^[a-z_][a-z0-9_]*$/.test(APP_ROLE)) {
    throw new Error(`APP role name is not a safe identifier: ${APP_ROLE}`);
  }

  await sql.unsafe(`
    do $$
    begin
      if not exists (select 1 from pg_roles where rolname = '${APP_ROLE}') then
        create role ${APP_ROLE} login password '${password}' nosuperuser nobypassrls;
      end if;
    end
    $$;
  `);
}
